// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.loader;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LoaderDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        RuleInspector inspector = new RuleInspector();

        // Bootstrap loader loads core classes → reported as null.
        inspector.reportLoader("java.lang.String", "hello".getClass());
        // Application/System loader loads our own classes.
        inspector.reportLoader("com.bank.loader.Account", rajesh.getClass());

        // Show the system (application) class loader and its parent chain.
        ClassLoader system = ClassLoader.getSystemClassLoader();
        log.info(() -> "System (Application) loader: " + system);
        log.info(() -> "  its parent (Platform) loader: " + system.getParent());
        log.info(() -> "  Platform's parent (Bootstrap): " + system.getParent().getParent());
    }
}

// ─── Would be in Account.java (an APPLICATION class) ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in FraudRule.java (plugin contract, could be custom-loaded) ───
interface FraudRule {
    boolean isSuspicious(BigDecimal amount);
}

// ─── Would be in RuleInspector.java ───
class RuleInspector {
    private static final Logger log = Logger.getLogger("BankLog");

    void reportLoader(String label, Class<?> type) {
        ClassLoader cl = type.getClassLoader();
        // Bootstrap loader is represented by null.
        String who = (cl == null) ? "Bootstrap (native, shown as null)" : cl.toString();
        log.info(() -> label + " loaded by: " + who);
    }
}
